import{_ as e,o as r,c as t,a5 as o}from"./chunks/framework.CXroN2RO.js";const c=JSON.parse('{"title":"疑問から選ぶ読み順","description":"","frontmatter":{"title":"疑問から選ぶ読み順","study":{"source":"統合ガイド","status":"published","generated":true,"catalog":true,"section":"learning","format":"path","domain":"guide","collection":"questions","order":0,"summary":"整数・浮動小数点、文字コード、メモリ確保、起動、同期、ファイルI/Oとマッピング、アセットロード、DNS・TCP・HTTP・TLS通信、入力と描画、Webの疑問から本文をたどる。"}},"headers":[],"relativePath":"guide/learning-paths.md","filePath":"guide/learning-paths.md"}'),i={name:"guide/learning-paths.md"};function l(s,a,h,n,d,u){return r(),t("div",null,[...a[0]||(a[0]=[o('<div id="読み進め方" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="疑問から選ぶ読み順" tabindex="-1">疑問から選ぶ読み順 <a class="header-anchor" href="#疑問から選ぶ読み順" aria-label="Permalink to &quot;疑問から選ぶ読み順&quot;">​</a></h1><p>辞典を最初から順番に読む必要はありません。いまの疑問に関係する本文から選びます。</p><h2 id="整数はメモリにどう並ぶか" tabindex="-1">整数はメモリにどう並ぶか <a class="header-anchor" href="#整数はメモリにどう並ぶか" aria-label="Permalink to &quot;整数はメモリにどう並ぶか&quot;">​</a></h2><ol><li><a href="/study/data/integer-bits-and-bytes.html">整数をビット列・16進数・バイト列で読む</a>で、値、表記、符号の解釈、バイト順を分ける。</li><li><a href="/study/practice/data/integer-byte-observation.html">C++の整数・バイト列観察サンプル</a>で、型の幅と実メモリ、明示的なLE/BE形式を比較する。</li><li><a href="/study/runtime/cpp-internals/memory-layout.html">メモリレイアウトとアラインメント</a>で、オブジェクトを置く場所やパディングとの違いを調べる。</li></ol><h2 id="floatで小さな差が消えるのはなぜか" tabindex="-1">floatで小さな差が消えるのはなぜか <a class="header-anchor" href="#floatで小さな差が消えるのはなぜか" aria-label="Permalink to &quot;floatで小さな差が消えるのはなぜか&quot;">​</a></h2><ol><li><a href="/study/data/floating-point-spacing.html">floatが表せる値と丸め</a>で、binary32の有効精度、表現できる値の間隔、丸めを調べる。</li><li><a href="/study/practice/data/float-spacing-observation.html">C++のfloat観察サンプル</a>で、ビット表現、隣接値、2の冪の境界、epsilonの意味を確かめる。</li><li><a href="/study/math/rendering/transform.html">座標変換</a>と<a href="/study/math/rendering/camera.html">カメラ・深度</a>で、描画で数値の尺度を扱う場面へつなぐ。</li></ol><h2 id="floatを等しいと判定するには" tabindex="-1">floatを等しいと判定するには <a class="header-anchor" href="#floatを等しいと判定するには" aria-label="Permalink to &quot;floatを等しいと判定するには&quot;">​</a></h2><ol><li><a href="/study/math/floating-point-comparison.html">浮動小数点の比較と許容差</a>で、厳密な等値と近似一致、単位を持つ絶対許容差と無次元の相対許容差を分ける。</li><li><a href="/study/practice/math/float-comparison-observation.html">C++・C#の比較サンプル</a>で、境界・NaN・Inf・非推移性・保存時に失われた座標差を確かめる。</li><li>表現できる値の間隔から調べたい場合は<a href="/study/data/floating-point-spacing.html">floatの刻み幅</a>へ戻る。</li></ol><h2 id="文字はどのようにバイト列になるか" tabindex="-1">文字はどのようにバイト列になるか <a class="header-anchor" href="#文字はどのようにバイト列になるか" aria-label="Permalink to &quot;文字はどのようにバイト列になるか&quot;">​</a></h2><ol><li><a href="/study/data/unicode-and-encoding.html">Unicodeと文字コード</a>で、コードポイント、UTF-8／UTF-16のコード単位、バイト列を分ける。</li><li><a href="/study/practice/data/unicode-observation.html">C++・C#の文字列観察サンプル</a>で、日本語・絵文字・結合文字の表現と、長さの数え方を比べる。</li><li><a href="/study/data/integer-bits-and-bytes.html">整数とバイト列</a>のエンディアンと結び付け、ファイルやAPIの文字コードを確認する。</li></ol><h2 id="「確保する」と内部で何が起きるか" tabindex="-1">「確保する」と内部で何が起きるか <a class="header-anchor" href="#「確保する」と内部で何が起きるか" aria-label="Permalink to &quot;「確保する」と内部で何が起きるか&quot;">​</a></h2><ol><li><a href="/study/runtime/memory/storage-duration-and-lifetime.html">記憶域期間・スコープ・寿命</a>を区別する。</li><li><a href="/study/runtime/memory/allocation-journey.html">malloc/newの内部</a>で、空き領域の再利用、必要時のOS要求、構築・破棄を追う。</li><li><a href="/study/os/virtual-memory.html">仮想メモリ</a>で、アドレス空間、ページ、予約・コミット・常駐、ページフォルトを区別する。</li><li><a href="/study/practice/memory/windows-memory-observation.html">Windows/C++の観察サンプル</a>で、予約・コミット・初回書込み・解放を実際に分けて確かめる。</li><li><a href="/study/runtime/memory/allocators-and-pools.html">用途別アロケータ</a>、<a href="/study/runtime/memory/memory-bugs.html">メモリバグ</a>、<a href="/study/runtime/memory/cache-locality-aos-soa.html">キャッシュ局所性</a>へ進む。</li></ol><h2 id="ソースコードがcpuで動くまで" tabindex="-1">ソースコードがCPUで動くまで <a class="header-anchor" href="#ソースコードがcpuで動くまで" aria-label="Permalink to &quot;ソースコードがCPUで動くまで&quot;">​</a></h2><ol><li><a href="/study/runtime/cpp-internals/build-pipeline-journey.html">ビルドの旅</a>でコンパイルとリンクをたどる。</li><li><a href="/study/runtime/cpp-internals/translation-units-and-headers.html">翻訳単位・ヘッダー</a>、<a href="/study/runtime/cpp-internals/symbols-and-linkage.html">シンボル・ABI</a>、<a href="/study/runtime/cpp-internals/object-files-and-libraries.html">実行ファイル・ライブラリ</a>を調べる。</li><li><a href="/study/os/process-startup.html">実行ファイルを起動してmainへ到達するまで</a>で、プロセス・スレッド、ローダー、CRTの役割を分ける。</li><li><a href="/study/practice/process/windows-process-observation.html">Windows/C++のプロセス観察</a>で、main前の記録、親子プロセス、ワーカースレッドのPID・TIDを確かめる。</li><li><a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">関数呼び出し・レジスタ</a>へ進む。</li></ol><h2 id="スレッド間でデータを安全に共有するには" tabindex="-1">スレッド間でデータを安全に共有するには <a class="header-anchor" href="#スレッド間でデータを安全に共有するには" aria-label="Permalink to &quot;スレッド間でデータを安全に共有するには&quot;">​</a></h2><ol><li><a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>で、共有状態と不変条件、同じロックで守る範囲、データを受け渡す順序を調べる。</li><li><a href="/study/practice/threads/inventory-synchronization.html">C++・C#の在庫消費サンプル</a>で、確認と消費、Snapshot、終了待ちと寿命を確かめる。</li><li><a href="/study/runtime/memory/concurrency-bugs.html">並行処理のバグ</a>で、データ競合・競合状態・false sharingの違いを調べる。</li></ol><h2 id="ファイルを読むと内部で何が起きるか" tabindex="-1">ファイルを読むと内部で何が起きるか <a class="header-anchor" href="#ファイルを読むと内部で何が起きるか" aria-label="Permalink to &quot;ファイルを読むと内部で何が起きるか&quot;">​</a></h2><ol><li><a href="/study/os/file-read-journey.html">ファイルを読む仕組み</a>で、アプリのバッファ、OSのファイルキャッシュ、ストレージへの要求を分ける。</li><li><a href="/study/practice/io/file-read-observation.html">C++・C#の読み取り観察</a>で、要求数と実読取数、ファイル位置、EOF、seek、失敗を確かめる。</li><li>テキストとして解釈するときは<a href="/study/data/unicode-and-encoding.html">Unicodeと文字コード</a>へ進む。</li></ol><h2 id="i-oの完了を待ちながら、別の処理を進めるには" tabindex="-1">I/Oの完了を待ちながら、別の処理を進めるには <a class="header-anchor" href="#i-oの完了を待ちながら、別の処理を進めるには" aria-label="Permalink to &quot;I/Oの完了を待ちながら、別の処理を進めるには&quot;">​</a></h2><ol><li><a href="/study/os/asynchronous-file-io.html">非同期I/O</a>で、要求の発行と完了、即時完了、待機と継続、バッファの寿命を分ける。</li><li><a href="/study/practice/io/async-file-read-observation.html">C++・C#の同期・非同期比較</a>で、同じファイルを読み、完了結果と内容の一致を確かめる。</li><li>複数の処理から状態を共有するときは<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>も確認する。</li></ol><h2 id="ファイルをメモリへのアクセスとして読むには" tabindex="-1">ファイルをメモリへのアクセスとして読むには <a class="header-anchor" href="#ファイルをメモリへのアクセスとして読むには" aria-label="Permalink to &quot;ファイルをメモリへのアクセスとして読むには&quot;">​</a></h2><ol><li><a href="/study/os/memory-mapped-files.html">メモリマップドファイル</a>で、ファイル内位置と仮想アドレス、ページフォルト、ビューの寿命を分ける。</li><li><a href="/study/practice/io/mapped-file-observation.html">C++・C#の読み取り専用マッピング</a>で、通常のreadと内容を照合し、整列した位置と使いたい範囲の対応を確かめる。</li><li>アドレス変換の基礎は<a href="/study/os/virtual-memory.html">仮想メモリ</a>、実行時の組立ては<a href="/study/game/asset-loading.html">アセットロード設計</a>へ進む。</li></ol><h2 id="アセットが読み終わってから、ゲームで使えるまで" tabindex="-1">アセットが読み終わってから、ゲームで使えるまで <a class="header-anchor" href="#アセットが読み終わってから、ゲームで使えるまで" aria-label="Permalink to &quot;アセットが読み終わってから、ゲームで使えるまで&quot;">​</a></h2><ol><li><a href="/study/game/asset-loading.html">アセットロード設計</a>で、読み取り、展開・検証、登録、利用可能化、解放を分ける。</li><li><a href="/study/practice/assets/asset-lifecycle-model.html">C++・C#の状態と寿命のモデル</a>で、古い要求の完了、キャンセル、失敗を含む所有権の移動を確かめる。</li><li>実I/Oの完了待ちは<a href="/study/os/asynchronous-file-io.html">非同期I/O</a>、共有するキューや状態の保護は<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>も確認する。</li></ol><h2 id="入力からゲーム画面まで" tabindex="-1">入力からゲーム画面まで <a class="header-anchor" href="#入力からゲーム画面まで" aria-label="Permalink to &quot;入力からゲーム画面まで&quot;">​</a></h2><ol><li><a href="/study/game/patterns/game-loop-and-update.html">ゲームループ</a>で入力・更新・描画の時間を分ける。</li><li><a href="/study/game/ecs.html">ECS</a>でID、データ配置、Query、構成変更を調べる。</li><li><a href="/study/math/rendering/transform.html">座標変換</a>と<a href="/study/graphics/pipeline/overview.html">描画パイプライン</a>から画面へつなぐ。</li><li>作って試すなら<a href="/study/game/shooter-design.html">シューティングの設計</a>を読み、<a href="/study/game/shooter-cpp.html">C++版</a>または<a href="/study/game/shooter-unity.html">Unity版</a>へ進む。</li></ol><h2 id="sendしたデータが、相手のアプリへ届くまで" tabindex="-1">sendしたデータが、相手のアプリへ届くまで <a class="header-anchor" href="#sendしたデータが、相手のアプリへ届くまで" aria-label="Permalink to &quot;sendしたデータが、相手のアプリへ届くまで&quot;">​</a></h2><ol><li><a href="/study/network/tcp-sockets.html">ソケットとTCP通信</a>で、IP・ポート、送受信バッファ、バイト列とメッセージ、半閉鎖を分ける。</li><li><a href="/study/practice/network/tcp-loopback-observation.html">C++・C#のローカル通信</a>で、長さ付きメッセージを復元し、送信停止後の応答と受信EOFを確かめる。</li><li>待機と非同期処理の基本は<a href="/study/os/asynchronous-file-io.html">非同期I/O</a>へ進む。今回の通信例は、非ブロッキング操作とreadiness待ちを使う。</li></ol><h2 id="tcpのバイト列が、webの要求と応答になるまで" tabindex="-1">TCPのバイト列が、Webの要求と応答になるまで <a class="header-anchor" href="#tcpのバイト列が、webの要求と応答になるまで" aria-label="Permalink to &quot;TCPのバイト列が、Webの要求と応答になるまで&quot;">​</a></h2><ol><li><a href="/study/network/http-messages.html">HTTP通信</a>で、要求行、状態コード、ヘッダー、本文の形式と長さを分ける。</li><li><a href="/study/practice/network/http-message-observation.html">C++・C#のHTTP観察</a>で、ローカルのGETと応答を照合し、本文のバイト数と文字数、メッセージ完成とEOFを確かめる。</li><li>下の層から調べる場合は<a href="/study/network/tcp-sockets.html">TCPとソケット</a>、文字の表現は<a href="/study/data/unicode-and-encoding.html">Unicodeと文字コード</a>へ戻る。</li></ol><h2 id="保存したhttp応答を、いつ再利用できるか" tabindex="-1">保存したHTTP応答を、いつ再利用できるか <a class="header-anchor" href="#保存したhttp応答を、いつ再利用できるか" aria-label="Permalink to &quot;保存したHTTP応答を、いつ再利用できるか&quot;">​</a></h2><ol><li><a href="/study/network/http-caching.html">HTTPキャッシュ</a>で、保存、freshness、再検証、Cache-Control、ETagと304の役割を調べる。</li><li><a href="/study/practice/network/http-cache-observation.html">C++・C#のHTTP再検証</a>で、ローカルサーバーへ条件付きGETを送り、304に本文がないことと、保存した本文を使う流れを確かめる。</li><li>メッセージの構造は<a href="/study/network/http-messages.html">HTTP通信</a>、本文を段階的に扱う仕組みは<a href="/study/browser/streams-backpressure.html">Streams API</a>へつなげる。</li></ol><h2 id="名前から、接続先のip候補が決まるまで" tabindex="-1">名前から、接続先のIP候補が決まるまで <a class="header-anchor" href="#名前から、接続先のip候補が決まるまで" aria-label="Permalink to &quot;名前から、接続先のIP候補が決まるまで&quot;">​</a></h2><ol><li><a href="/study/network/dns-resolution.html">DNSと名前解決</a>で、OSの名前解決、再帰リゾルバー、権威DNS、レコードとキャッシュを分ける。</li><li><a href="/study/practice/network/name-resolution-observation.html">C++・C#の名前解決観察</a>で、数値IP・localhost・追加指定する公開名を調べ、APIの結果から分かる範囲を確かめる。</li><li>IPを得た後の接続は<a href="/study/network/tcp-sockets.html">TCPとソケット</a>、要求と応答は<a href="/study/network/http-messages.html">HTTP通信</a>へ進む。</li></ol><h2 id="httpsで暗号化し、接続相手を確かめるには" tabindex="-1">HTTPSで暗号化し、接続相手を確かめるには <a class="header-anchor" href="#httpsで暗号化し、接続相手を確かめるには" aria-label="Permalink to &quot;HTTPSで暗号化し、接続相手を確かめるには&quot;">​</a></h2><ol><li><a href="/study/network/tls-https.html">TLS・証明書・HTTPS</a>で、鍵共有、証明書、相手名の検証、暗号化したHTTPの関係を調べる。</li><li><a href="/study/practice/network/https-observation.html">C++・C#のHTTPS観察</a>で、標準の証明書検証を保ち、APIが返す接続情報とHTTP応答を確かめる。</li><li>接続先の候補は<a href="/study/network/dns-resolution.html">DNSと名前解決</a>、要求の意味は<a href="/study/network/http-messages.html">HTTP通信</a>で確認する。</li></ol><h2 id="urlを開いてからページが見えるまで" tabindex="-1">URLを開いてからページが見えるまで <a class="header-anchor" href="#urlを開いてからページが見えるまで" aria-label="Permalink to &quot;URLを開いてからページが見えるまで&quot;">​</a></h2><ol><li>通信は<a href="/study/network/dns-resolution.html">DNSと名前解決</a>、<a href="/study/network/tcp-sockets.html">TCPとソケット</a>、<a href="/study/network/http-messages.html">HTTPの要求と応答</a>、<a href="/study/network/tls-https.html">TLS・証明書・HTTPS</a>で調べる。</li><li><a href="/study/browser/rendering-journey.html">ブラウザの描画</a>で、受信したHTMLからDOM、スタイル、レイアウト、描画、合成までをつなぐ。</li><li><a href="/study/practice/browser/render-observation.html">DOMと描画の変化を観察する</a>で、幅・色・移動・透明度を変え、寸法APIとrAFで確認できる範囲を試す。</li></ol><h2 id="promiseやawaitの続きは、いつ動くのか" tabindex="-1">Promiseやawaitの続きは、いつ動くのか <a class="header-anchor" href="#promiseやawaitの続きは、いつ動くのか" aria-label="Permalink to &quot;Promiseやawaitの続きは、いつ動くのか&quot;">​</a></h2><ol><li><a href="/study/browser/event-loop-promises.html">イベントループ・Promise・async/await</a>で、同期処理、タスク、マイクロタスク、描画機会を区別する。</li><li><a href="/study/practice/browser/event-loop-observation.html">Promiseとawaitの実行順を観察する</a>で、有限のコードから実行順を記録する。timerとrAFの相対順は固定しない。</li><li>画面の更新は<a href="/study/browser/rendering-journey.html">ブラウザの描画</a>、要求の発行と完了は<a href="/study/os/asynchronous-file-io.html">非同期I/O</a>へつなげる。</li></ol><h2 id="メイン側とは別の実行主体へ、仕事とデータを渡すには" tabindex="-1">メイン側とは別の実行主体へ、仕事とデータを渡すには <a class="header-anchor" href="#メイン側とは別の実行主体へ、仕事とデータを渡すには" aria-label="Permalink to &quot;メイン側とは別の実行主体へ、仕事とデータを渡すには&quot;">​</a></h2><ol><li><a href="/study/browser/web-workers-messages.html">Web Workerとメッセージ通信</a>で、実行の分担、メッセージの受信、コピーと転送、寿命を区別する。</li><li><a href="/study/practice/browser/worker-message-observation.html">Workerのコピー・転送・停止を観察する</a>で、16バイトの往復、バッファの切り離し、要求ID、停止と再起動を試す。</li><li>同じ実行先の続きを扱う<a href="/study/browser/event-loop-promises.html">イベントループ・Promise・async/await</a>と、共有状態を守る<a href="/study/runtime/thread-synchronization.html">スレッド同期</a>へつなげる。</li></ol><h2 id="依頼が増えたとき、workerと待ち行列をどう管理するか" tabindex="-1">依頼が増えたとき、Workerと待ち行列をどう管理するか <a class="header-anchor" href="#依頼が増えたとき、workerと待ち行列をどう管理するか" aria-label="Permalink to &quot;依頼が増えたとき、Workerと待ち行列をどう管理するか&quot;">​</a></h2><ol><li><a href="/study/browser/worker-pool-backpressure.html">Worker poolと待ち行列の制御</a>で、受付数・実行数・待機数、上流への抑制、取消しと終了を区別する。</li><li><a href="/study/practice/browser/worker-pool-observation.html">Worker poolの待機数と取消しを観察する</a>で、2実行・4待機・1拒否、待機の取消しと結果破棄による違いを確かめる。</li><li><a href="/study/browser/web-workers-messages.html">Web Workerの通信</a>でデータの受け渡しを確認し、<a href="/study/game/asset-loading.html">アセットロード</a>の段階と利用可能になる条件へつなぐ。</li></ol><h2 id="読み込みより処理が遅いとき、供給をどう抑えるか" tabindex="-1">読み込みより処理が遅いとき、供給をどう抑えるか <a class="header-anchor" href="#読み込みより処理が遅いとき、供給をどう抑えるか" aria-label="Permalink to &quot;読み込みより処理が遅いとき、供給をどう抑えるか&quot;">​</a></h2><ol><li><a href="/study/browser/streams-backpressure.html">Streams APIとストリーミング処理</a>で、chunk、queue、pull、バックプレッシャー、終了の伝播を区別する。</li><li><a href="/study/practice/browser/stream-backpressure-observation.html">Streams APIで供給と処理の速度差を観察する</a>で、有限のデータを遅いsinkへ送り、先読みと中断を確かめる。</li><li>仕事の受付数は<a href="/study/browser/worker-pool-backpressure.html">Worker pool</a>、文字の境界は<a href="/study/data/unicode-and-encoding.html">Unicodeとエンコーディング</a>、利用可能になる条件は<a href="/study/game/asset-loading.html">アセットロード</a>へつなげる。</li></ol><h2 id="ブラウザのどこへ保存し、いつまで残るのか" tabindex="-1">ブラウザのどこへ保存し、いつまで残るのか <a class="header-anchor" href="#ブラウザのどこへ保存し、いつまで残るのか" aria-label="Permalink to &quot;ブラウザのどこへ保存し、いつまで残るのか&quot;">​</a></h2><ol><li><a href="/study/browser/storage-lifetime.html">ブラウザの保存領域とデータの寿命</a>で、localStorage・IndexedDB・Cache API、保存区画、transaction、容量と保持方針を区別する。</li><li><a href="/study/practice/browser/storage-observation.html">保存・再読込・削除の観察</a>で、3方式へ固定データを保存し、ページ再読込後の読出しと専用データの削除を試す。</li><li>応答の自動的な再利用は<a href="/study/network/http-caching.html">HTTPキャッシュ</a>、Request／Responseの本文を扱う流れは<a href="/study/browser/streams-backpressure.html">Streams API</a>へつなげる。</li></ol><h2 id="通信できないとき、保存した応答をどう返すか" tabindex="-1">通信できないとき、保存した応答をどう返すか <a class="header-anchor" href="#通信できないとき、保存した応答をどう返すか" aria-label="Permalink to &quot;通信できないとき、保存した応答をどう返すか&quot;">​</a></h2><ol><li><a href="/study/browser/service-worker-offline.html">Service Workerとオフライン動作</a>で、登録・有効化・ページの制御、fetchへの介入と応答の選択を調べる。</li><li><a href="/study/practice/browser/service-worker-observation.html">Service Workerで応答元と登録状態を観察する</a>で、専用scopeの登録、固定GETの代替応答、解除と後片付けを試す。</li><li>応答の明示的な保存は<a href="/study/browser/storage-lifetime.html">ブラウザの保存領域</a>、HTTPの再利用と再検証は<a href="/study/network/http-caching.html">HTTPキャッシュ</a>で確認する。</li></ol><h2 id="別オリジンへの通信で、応答を読めるかは何で決まるか" tabindex="-1">別オリジンへの通信で、応答を読めるかは何で決まるか <a class="header-anchor" href="#別オリジンへの通信で、応答を読めるかは何で決まるか" aria-label="Permalink to &quot;別オリジンへの通信で、応答を読めるかは何で決まるか&quot;">​</a></h2><ol><li><a href="/study/browser/same-origin-cors.html">同一オリジンポリシーとCORS</a>で、文書間の境界、応答の公開、preflightによる事前確認を区別する。</li><li><a href="/study/practice/browser/cors-observation.html">ブラウザでCORSの応答を比べる</a>で、通常ページとsandboxから同じデータをGETし、公開版とローカル配信で結果を比べる。</li><li><a href="/study/network/http-messages.html">HTTPメッセージ</a>で要求・応答を確認し、<a href="/study/network/http-caching.html">HTTPキャッシュ</a>で応答を再利用する条件へつなげる。</li></ol><h2 id="ページをまたいで、サーバーが同じセッションをどう見つけるか" tabindex="-1">ページをまたいで、サーバーが同じセッションをどう見つけるか <a class="header-anchor" href="#ページをまたいで、サーバーが同じセッションをどう見つけるか" aria-label="Permalink to &quot;ページをまたいで、サーバーが同じセッションをどう見つけるか&quot;">​</a></h2><ol><li><a href="/study/browser/cookies-and-sessions.html">Cookieとセッション</a>で、Cookieを送る条件、サーバーによるIDの照合、ログアウト時の失効を区別する。</li><li><a href="/study/practice/browser/cookie-session-observation.html">Cookieの範囲とセッションIDを観察する</a>で、Pathによる見え方と、HttpOnlyのIDが次の要求に付くところを確かめる。</li><li>別オリジンでの応答の読み取りは<a href="/study/browser/same-origin-cors.html">CORS</a>、ブラウザ内でのデータ保持は<a href="/study/browser/storage-lifetime.html">ブラウザの保存領域</a>へつなげる。</li></ol><h2 id="表示する文字列がhtmlやコードに変わるのはどこか" tabindex="-1">表示する文字列がHTMLやコードに変わるのはどこか <a class="header-anchor" href="#表示する文字列がhtmlやコードに変わるのはどこか" aria-label="Permalink to &quot;表示する文字列がHTMLやコードに変わるのはどこか&quot;">​</a></h2><ol><li><a href="/study/browser/xss-and-csp.html">XSSとCSP</a>で、入力元、HTMLとして解釈する箇所、スクリプトの実行条件を区別する。</li><li><a href="/study/practice/browser/xss-csp-observation.html">textContent・innerHTML・CSPの観察</a>で、同じ入力が文字・要素・イベント処理になる違いを確かめる。</li><li>DOMができる段階は<a href="/study/browser/rendering-journey.html">ブラウザの描画</a>、スクリプトからCookieを読める条件は<a href="/study/browser/cookies-and-sessions.html">Cookieとセッション</a>へつなげる。</li></ol><h2 id="cookie付きの要求をどの条件で受理するか" tabindex="-1">Cookie付きの要求をどの条件で受理するか <a class="header-anchor" href="#cookie付きの要求をどの条件で受理するか" aria-label="Permalink to &quot;Cookie付きの要求をどの条件で受理するか&quot;">​</a></h2><ol><li><a href="/study/browser/csrf-and-request-validation.html">CSRFとリクエスト検証</a>で、Cookieが届く条件、送信元の照合、セッションとトークンの照合を区別する。</li><li><a href="/study/practice/browser/csrf-observation.html">CSRFでCookie付きの要求が届く条件を観察する</a>で、同一サイトの別オリジンからフォームを送り、受理と拒否を比べる。</li><li>Cookieの送信条件は<a href="/study/browser/cookies-and-sessions.html">Cookieとセッション</a>、別オリジンの応答公開は<a href="/study/browser/same-origin-cors.html">CORS</a>で確認する。</li></ol><h2 id="ブラウザのworkerと、同じメモリを共有するには" tabindex="-1">ブラウザのWorkerと、同じメモリを共有するには <a class="header-anchor" href="#ブラウザのworkerと、同じメモリを共有するには" aria-label="Permalink to &quot;ブラウザのWorkerと、同じメモリを共有するには&quot;">​</a></h2><ol><li><a href="/study/browser/cross-origin-isolation.html">クロスオリジン分離と共有メモリ</a>で、COOP・COEP・CORPと、分離状態が成立する条件を整理する。</li><li><a href="/study/practice/browser/cross-origin-isolation-observation.html">Workerへのコピーと共有メモリを観察する</a>で、4種類のヘッダー設定と、コピー・共有の結果を比べる。</li><li>データの転送は<a href="/study/browser/web-workers-messages.html">Web Workerとメッセージ通信</a>、並行処理の同期は<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>へつなげる。</li></ol><h2 id="webassemblyから整数を読み書きするには" tabindex="-1">WebAssemblyから整数を読み書きするには <a class="header-anchor" href="#webassemblyから整数を読み書きするには" aria-label="Permalink to &quot;WebAssemblyから整数を読み書きするには&quot;">​</a></h2><ol><li><a href="/study/browser/webassembly-linear-memory.html">WebAssemblyと線形メモリ</a>で、モジュールのバイナリ、インスタンス、バイト位置と境界チェックを区別する。</li><li><a href="/study/practice/browser/wasm-memory-observation.html">WebAssemblyの読み込みと線形メモリを観察する</a>で、JavaScriptとWasmから同じバイト列を読み、拡張前後のビューを比べる。</li><li>バイト列での整数の表現は<a href="/study/data/integer-bits-and-bytes.html">整数とビット・バイト</a>、Workerをまたぐ共有は<a href="/study/browser/cross-origin-isolation.html">クロスオリジン分離と共有メモリ</a>で確認する。</li></ol><h2 id="配列や文字列をwasmへ渡すとき、どこに何を置くか" tabindex="-1">配列や文字列をWasmへ渡すとき、どこに何を置くか <a class="header-anchor" href="#配列や文字列をwasmへ渡すとき、どこに何を置くか" aria-label="Permalink to &quot;配列や文字列をWasmへ渡すとき、どこに何を置くか&quot;">​</a></h2><ol><li><a href="/study/browser/wasm-data-and-allocation.html">WebAssemblyのデータ受け渡しとメモリ確保</a>で、ポインタと長さの単位、配置、確保位置とメモリの容量を整理する。</li><li><a href="/study/practice/browser/wasm-abi-observation.html">Wasmへ配列とUTF-8を渡す実験</a>で、実際のバイト列、アラインメントによる空き、確保失敗と拡張を観察する。</li><li>文字列のバイト表現は<a href="/study/data/unicode-and-encoding.html">Unicodeとエンコーディング</a>、メモリ確保を実行環境の内側から見る場合は<a href="/study/runtime/memory/allocation-journey.html">メモリ確保の内部</a>へつなげる。</li></ol><h2 id="_2つのworkerが同じ値を更新すると何が起きるか" tabindex="-1">2つのWorkerが同じ値を更新すると何が起きるか <a class="header-anchor" href="#_2つのworkerが同じ値を更新すると何が起きるか" aria-label="Permalink to &quot;2つのWorkerが同じ値を更新すると何が起きるか&quot;">​</a></h2><ol><li><a href="/study/browser/shared-memory-atomics.html">Web Workerと共有メモリの同期</a>で、失われた更新、不可分な加算、待機と通知を区別する。</li><li><a href="/study/practice/browser/atomics-observation.html">Workerの競合とAtomicsの待機・通知を観察する</a>で、読み取りと書き込みの順序をたどる。実際のWorkerで確認する場合はローカル配信を使う。</li><li>共有できる条件は<a href="/study/browser/cross-origin-isolation.html">クロスオリジン分離と共有メモリ</a>、複数の値を一緒に守る設計は<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>で調べる。</li></ol><h2 id="固定サイズのメモリで値を順番に渡すには" tabindex="-1">固定サイズのメモリで値を順番に渡すには <a class="header-anchor" href="#固定サイズのメモリで値を順番に渡すには" aria-label="Permalink to &quot;固定サイズのメモリで値を順番に渡すには&quot;">​</a></h2><ol><li><a href="/study/browser/spsc-ring-buffer.html">リングバッファとSPSCキュー</a>で、読み書き位置が末尾から先頭に戻る仕組みと、空・満杯の判定を整理する。</li><li><a href="/study/practice/browser/ring-buffer-observation.html">リングバッファの満杯・折り返し・読み出し順を観察する</a>で、満杯で拒否された値を空きができてから入れ直し、読み出し順を比べる。</li><li>異なるWorkerへの公開順序は<a href="/study/browser/shared-memory-atomics.html">Web Workerと共有メモリの同期</a>、受付を制御する方針は<a href="/study/browser/worker-pool-backpressure.html">Worker poolとバックプレッシャー</a>へつなげる。</li></ol><h2 id="音声データが出力に間に合わないと何が起きるか" tabindex="-1">音声データが出力に間に合わないと何が起きるか <a class="header-anchor" href="#音声データが出力に間に合わないと何が起きるか" aria-label="Permalink to &quot;音声データが出力に間に合わないと何が起きるか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-worklet-buffering.html">AudioWorkletと音声バッファ</a>で、サンプルフレーム、レンダリングの処理単位、データの供給不足を区別する。</li><li><a href="/study/practice/browser/audio-buffer-observation.html">AudioWorkletで先読みとアンダーランを観察する</a>で、同じ到着の遅れを与え、先読みの有無で波形と不足したフレーム数を比べる。</li><li>待ち行列で枠を使い回す仕組みは<a href="/study/browser/spsc-ring-buffer.html">リングバッファとSPSCキュー</a>で確認する。</li></ol><h2 id="複数の音を重ねると波形はどう変わるか" tabindex="-1">複数の音を重ねると波形はどう変わるか <a class="header-anchor" href="#複数の音を重ねると波形はどう変わるか" aria-label="Permalink to &quot;複数の音を重ねると波形はどう変わるか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-mixing-and-headroom.html">Web Audioのミキシング</a>で、音源ごとのゲイン、加算、出力までの振幅の余裕を確認する。</li><li><a href="/study/practice/browser/audio-mixing-observation.html">Web Audioでゲインとクリッピングを観察する</a>で、マスターゲインを変えてクリップ前後の波形とピークを比べる。</li><li>音声フレームの供給と出力の関係は<a href="/study/browser/audio-worklet-buffering.html">AudioWorkletと音声バッファ</a>で確認する。</li></ol><h2 id="再生中の音を急に消すと何が起きるか" tabindex="-1">再生中の音を急に消すと何が起きるか <a class="header-anchor" href="#再生中の音を急に消すと何が起きるか" aria-label="Permalink to &quot;再生中の音を急に消すと何が起きるか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-gain-automation.html">Web Audioのゲインオートメーション</a>で、音声の時刻に沿ってゲインが変わる仕組みと、急な消音で生じる波形の段差を確認する。</li><li><a href="/study/practice/browser/audio-fade-observation.html">Web Audioで急な消音とフェードを観察する</a>で、フェードの長さを変え、切り替え前後のサンプル値と波形を比べる。</li><li>複数の音を足し合わせる場合のゲインは<a href="/study/browser/audio-mixing-and-headroom.html">Web Audioのミキシング</a>で確認する。</li></ol><h2 id="二つの音を入れ替える途中で音量はどう変わるか" tabindex="-1">二つの音を入れ替える途中で音量はどう変わるか <a class="header-anchor" href="#二つの音を入れ替える途中で音量はどう変わるか" aria-label="Permalink to &quot;二つの音を入れ替える途中で音量はどう変わるか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-crossfade.html">Web Audioのクロスフェード</a>で、二つのゲインの形と、音源の相関が加算結果にどう関わるかを確認する。</li><li><a href="/study/practice/browser/audio-crossfade-observation.html">Web Audioで線形と等電力のクロスフェードを比べる</a>で、音源の組み合わせを変え、切り替え前と中点付近の実効値を比べる。</li><li>ゲインを音声の時刻で変える仕組みは<a href="/study/browser/audio-gain-automation.html">Web Audioのゲインオートメーション</a>で確認する。</li></ol><h2 id="同じ音を少し遅らせて重ねると何が起きるか" tabindex="-1">同じ音を少し遅らせて重ねると何が起きるか <a class="header-anchor" href="#同じ音を少し遅らせて重ねると何が起きるか" aria-label="Permalink to &quot;同じ音を少し遅らせて重ねると何が起きるか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-comb-filter.html">Web Audioのコムフィルター</a>で、遅延した音を足すと周波数によって強め合ったり弱め合ったりする理由を確認する。</li><li><a href="/study/practice/browser/audio-comb-observation.html">Web Audioで遅延とコムフィルターを観察する</a>で、遅延時間とゲインを変え、最初にへこむ周波数を比べる。</li><li>二つの音を切り替える途中の実効値は<a href="/study/browser/audio-crossfade.html">Web Audioのクロスフェード</a>で確認する。</li></ol><h2 id="一つの音から反響を繰り返すには" tabindex="-1">一つの音から反響を繰り返すには <a class="header-anchor" href="#一つの音から反響を繰り返すには" aria-label="Permalink to &quot;一つの音から反響を繰り返すには&quot;">​</a></h2><ol><li><a href="/study/browser/audio-feedback-delay.html">Web Audioのフィードバックディレイ</a>で、出力を遅延経路に戻す接続と、繰り返すたびに振幅が小さくなる仕組みを確認する。</li><li><a href="/study/practice/browser/audio-feedback-observation.html">Web Audioで反響の間隔と減衰を観察する</a>で、遅延時間と戻すゲインを変え、反響の時刻と振幅を比べる。</li><li>遅延した入力を一度だけ重ねたときの周波数応答は<a href="/study/browser/audio-comb-filter.html">Web Audioのコムフィルター</a>で確認する。</li></ol><h2 id="作り方の変化を歴史から見る" tabindex="-1">作り方の変化を歴史から見る <a class="header-anchor" href="#作り方の変化を歴史から見る" aria-label="Permalink to &quot;作り方の変化を歴史から見る&quot;">​</a></h2><p><a href="/study/history/video-games.html">ビデオゲーム史</a>の作品・ハード・媒体・流通と、<a href="/study/guide/rendering/timeline.html">リアルタイム3D技術史</a>の技術の変化から、気になった仕組みへ進みます。</p>',83)])])}const f=e(i,[["render",l]]);export{c as __pageData,f as default};
